The sheaf $\mathcal{P}_E$ admits a left resolution of the following form for some $k_i \in \mathbb{Z}_{\geqslant 0}$
    \begin{align}
        \cdots \to \mathcal{V}_E^{\oplus k_1} \to \mathcal{V}_E^{\oplus k_0} \to \mathcal{P}_E \to 0.
    \end{align}

If $E\in \operatorname{Coh}^{\heartsuit}(\mathcal{C}_b)$ is semistable, we have 
\begin{align}
\mathcal{V}_E \in \widetilde{\operatorname{L}}(\mathcal{H})_{w'}. 
\end{align}

If $E$ is semistable, we have 
    \begin{align*}
        \mathcal{P}_E \in \widetilde{\operatorname{L}}(\mathcal{H})_{w'}.
    \end{align*}

We have 
\begin{align*}
\Phi(\mathcal{O}_{\mathcal{H}(w)^{\mathrm{ss}}})\in j_{!}\operatorname{L}(\mathcal{H}(\chi_0)^{\mathrm{ss}})_{w'}.
\end{align*}   
Here $j_{!}$ is the fully-faithful left adjoint of the pull-back $j^*$
for the open immersion $j \colon \mathcal{H}(\chi_0)^{\mathrm{ss}} \hookrightarrow \mathcal{H}(\chi_0)$
\begin{align*}j_{!} \colon \operatorname{L}(\mathcal{H}(\chi_0)^{\mathrm{ss}})_{w'} \hookrightarrow \operatorname{L}(\mathcal{H}(\chi_0))_{w'}.
\end{align*}

\emph{(Theorem~4.10)}
The Whittaker normalization Conjecture~1.4 is true over
$\mathcal{B}=\mathcal{B}^A$.
